def is_not_prime(n):
    """
    Returns True if n is not a prime number, False otherwise.
    """
    if n <= 1:
        return True
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


assert is_not_prime(2) == False, "is_not_prime(2) should be False"
assert is_not_prime(10) == True, "is_not_prime(10) should be True"
assert is_not_prime(35) == True, "is_not_prime(35) should be True"
assert is_not_prime(37) == False, "is_not_prime(37) should be False"

def find_char_long(s: str) -> set:
    """
    Returns a set of all words in the string that are at least 4 characters long.
    """
    return set(word for word in s.split() if len(word) >= 4)

def square_perimeter(side_length: int) -> int:
    """Return the perimeter of a square given its side length."""
    return side_length * 4
